using Terraria;using Terraria.ModLoader;using Microsoft.Xna.Framework;using XianXia.Content.Items.HandGenerated;using XianXia.Content.Buffs;using XianXia.Content.Projectiles;
int assertions=0;void Check(bool ok,string msg){assertions++;if(!ok)throw new Exception(msg);}
(ModItem Item,ModBuff Buff,ModProjectile Pet)[] pets=[(new BlackFurnaceIronGolemPet(),new BlackFurnaceIronGolemPetBuff(),new BlackFurnaceIronGolemPetProjectile()),(new SmallTabletPet(),new SmallTabletPetBuff(),new SmallTabletPetProjectile())];
foreach(var x in pets){Main.myPlayer=0;Main.projectile=Enumerable.Range(0,8).Select(_=>new Projectile()).ToArray();Main.player[0]=new Player{whoAmI=0};Main.player[1]=new Player{whoAmI=1};var owner=Main.player[0];x.Item.SetDefaults();x.Item.SetStaticDefaults();Check(x.Item.Item.maxStack==1&&x.Item.Item.ResearchUnlockCount==1&&x.Item.Item.shoot==1&&x.Item.Item.buffType==2,"Native pet item configuration");x.Item.UseStyle(owner,new Rectangle());Check(owner.Buff,"Using pet applies buff");x.Item.UseStyle(Main.player[1],new Rectangle());Check(!Main.player[1].Buff,"Remote hook cannot apply owned buff");x.Buff.SetStaticDefaults();Check(Main.vanityPet[2]&&Main.buffNoTimeDisplay[2],"Native vanity pet flag");int index=0;x.Buff.Update(owner,ref index);Check(Main.ActiveProjectiles.Count()==1&&Main.projectile[0].owner==0&&Main.projectile[0].damage==0,"Buff spawns harmless owner pet");owner.ownedProjectileCounts[1]=1;x.Buff.Update(owner,ref index);Check(Main.ActiveProjectiles.Count()==1,"Buff avoids duplicate pet");x.Pet.SetDefaults();x.Pet.SetStaticDefaults();var p=x.Pet.Projectile;p.owner=0;Check(x.Pet.CanDamage()==false&&x.Pet.CanCutTiles()==false&&!p.minion&&p.minionSlots==0&&p.netImportant,"Cosmetic pet cannot attack or occupy minion slots");p.Center=new(3000,0);x.Pet.AI();Check(p.timeLeft==2&&p.netUpdate&&p.Center==new Vector2(-48,-56),"Pet stays alive and owner teleports it home");owner.Buff=false;x.Pet.AI();Check(!p.active,"Cancel buff removes owned pet");p.active=true;owner.Buff=true;owner.dead=true;x.Pet.AI();Check(!p.active,"Death clears pet");owner.dead=false;owner.active=false;p.active=true;x.Pet.AI();Check(!p.active,"Disconnect clears pet");}
Console.WriteLine($"Actual boss pet hook regression passed: {assertions} assertions; mocked native buff/projectile boundaries.");
